// 1. Tokens do LLM principal (via Message a model com max_tokens:1)
const usage = $json.usage || {};
const llm_prompt    = usage.input_tokens  ?? 0;
const llm_completion = usage.output_tokens ?? 0;
const llm_total     = usage.total_tokens  ?? (llm_prompt + llm_completion);

// 2. Custo do Embedding (RAG - text-embedding-3-small)
let embedding_tokens = 0;
try {
  const embeddingUsage = $('HTTP Request - Embedings (msg usr)').first().json?.usage;
  embedding_tokens = embeddingUsage?.prompt_tokens ?? 0;
} catch(e) { embedding_tokens = 0; }

// 3. Passa o modelo configurado no agente
const modelId = $('Edit Fields').first().json?.agent?.modelId || 'gpt-4o-mini';

return [{
  json: {
    prompt_tokens:     llm_prompt + embedding_tokens, // Total input cost
    completion_tokens: llm_completion,                // 1 token (medição)
    total_tokens:      llm_total + embedding_tokens,
    llm_prompt_tokens: llm_prompt,
    embedding_tokens:  embedding_tokens,
    model:             modelId
  }
}];

const PRICES = {
  'gpt-4o-mini': { input: 0.15, output: 0.60 },
  'gpt-4o':      { input: 5.00, output: 15.0  }
};
const EMBEDDING_PRICE_PER_M_USD = 0.02; // text-embedding-3-small
const BRL_RATE = 6.0;

const model = $json.model || 'gpt-4o-mini';
const price = PRICES[model] || PRICES['gpt-4o-mini'];

// Custo LLM (input = system prompt + RAG context + user msg; output = 1 token)
const llmCostUSD = 
  (($json.llm_prompt_tokens || 0) / 1_000_000) * price.input +
  (($json.completion_tokens  || 0) / 1_000_000) * price.output;

// Custo Embedding (muito pequeno mas real)
const embCostUSD = (($json.embedding_tokens || 0) / 1_000_000) * EMBEDDING_PRICE_PER_M_USD;

const totalUSD = llmCostUSD + embCostUSD;

return [{
  json: {
    ...$json,
    cost_usd:           Number(totalUSD.toFixed(6)),
    cost_brl:           Number((totalUSD * BRL_RATE).toFixed(6)),
    cost_usd_llm:       Number(llmCostUSD.toFixed(6)),
    cost_usd_embedding: Number(embCostUSD.toFixed(6))
  }
}];

