/* 
  🛡️ ORGANIZADOR DE CONTEXTO (GENERALE V17)
  - n8n Burro: Apenas organiza os dados brutos.
  - Segurança: Bloqueia ferramentas se o usuário trocar o CPF no meio.
*/

// 1. Coleta de dados genéricos (presentes em qualquer Agente do fluxo)
const editFields = $('Edit Fields').first().json;
const intentNode = $('formatacao Intencao').first().json;
const rpcAgente = $('Buscar Agente - RPC').first().json;

const intent = intentNode.intent || 'general';
const userMsg = editFields.message || '';

// Identifica se a mensagem atual é um CPF/CNPJ
const cleanInput = userMsg.replace(/[^\d]/g, '');
const isDocInput = /^\d{11}$|^\d{14}$/.test(cleanInput);

// 2. Estado de Autenticação
const isAuth = (editFields.security_status === 'active');
const currentDoc = editFields.validated_doc || editFields.session_identifier;

// 3. Regra de Segurança (Troca de documento)
let should_use_tools = (intent === 'general' || isAuth);

// Se o usuário digitou um novo DOC e ele é diferente do atual logado, bloqueamos
if (isDocInput && cleanInput !== currentDoc) {
  should_use_tools = false;
}

// 4. Montagem do Contexto para o LLM (Entrega de Dados)
// Aqui passamos os dados que as TOOLS vão precisar como parâmetros (p_cpf, p_agent_id, etc)
let contextText = `\n\n[SISTEMA - STATUS]: `;

if (isAuth) {
    contextText += `AUTENTICADO.
    - p_cpf: ${currentDoc}
    - p_agent_id: ${editFields.agent_id}
    - p_conversation_id: ${rpcAgente.conversation?.id}`;
} else if (isDocInput && !should_use_tools) {
    contextText += `PROCESSANDO DOCUMENTO INFORMADO: ${cleanInput}...`;
} else {
    contextText += `NÃO IDENTIFICADO. SOLICITE IDENTIFICAÇÃO SE NECESSÁRIO.`;
}

return [{ 
    json: { 
        strategies_context: contextText,
        detected_intent: intent,
        should_use_tools: should_use_tools,
        current_user_input_doc: isDocInput ? cleanInput : null,
        // Campos auxiliares para o n8n
        authenticated_id: currentDoc,
        auth_status: isAuth ? 'active' : 'none'
    } 
}];

