/* 
  🔐 CONTEXTO PÓS-AUTENTICAÇÃO (V17 - n8n Burro)
*/

// 1. Pega os dados mais frescos (da validação que acabou de passar)
const validation = $('Validar_Documento_Security_Gate').first().json;
const agentData = $('Edit Fields').first().json;
const rpcAgente = $('Buscar Agente - RPC').first().json;
const history = rpcAgente.conversation?.history || [];

// 2. n8n Burro: Localiza o último pedido do usuário para não perder o fio da meada
const userMessages = history
    .filter(m => (m.role === 'user' || m.sender_type === 'user'))
    .map(m => m.content || m.message || '')
    .filter(msg => {
        const clean = msg.replace(/[^\d]/g, '');
        return !(/^\d{11}$|^\d{14}$/.test(clean)); // Ignora a mensagem que era só o CPF
    });

const lastRequest = userMessages.length > 0 ? userMessages[userMessages.length - 1] : "o que eu pedi antes";

// 3. Montagem do Contexto (Entrega de "Tijolos" para a ferramenta)
let contextText = `\n\n[SISTEMA - SEGURANÇA]: IDENTIDADE CONFIRMADA AGORA.
   - p_cpf: ${validation.active_cpf} 
   - p_agent_id: ${agentData.agent_id}
   - p_conversation_id: ${rpcAgente.conversation?.id}

   ⚠️ INSTRUÇÃO PRIORITÁRIA: O cliente foi autenticado com sucesso. 
   Não peça o CPF. Atenda ao pedido: "${lastRequest}" usando a ferramenta 'Consultar_Vida_Financeira' IMEDIATAMENTE.`;

return [{
    json: {
        strategies_context: contextText,
        detected_intent: 'protected',
        should_use_tools: true, // Libera a IA para agir
        authenticated_id: validation.active_cpf
    }
}];

/* 🛡️ EXTRATOR DE IMAGEM - VERSÃO ESTÁVEL */
const allItems = items;
const output = [];

// 1. Busca o Base64 uma única vez fora do loop para não travar
let base64Data = null;
try {
  base64Data = $("Obter mídia base64").first().json.data.base64;
} catch (e) {
  try {
    base64Data = $("Obter midia base64").first().json.data.base64;
  } catch (ee) {}
}

// 2. Processa os itens de forma simples
for (let item of allItems) {
  let jsonData = item.json;
  if (Array.isArray(jsonData)) jsonData = jsonData[0];

  let extractedText = "Sem texto extraído";
  try {
    extractedText = (jsonData.content && jsonData.content[0] && jsonData.content[0].text) || 
                    jsonData.text || 
                    jsonData.output || 
                    extractedText;
  } catch (err) {}

  output.push({
    json: {
      message: extractedText,
      image_base64: base64Data,
      message_type: 'imageMessage'
    }
  });
}

return output;

/* 
  🛡️ INTENT FORMATTER & SAFETY NET (V31 - OPTIMIZED)
  Garante que saudações não sejam classificadas erroneamente como general.
*/

let iaText = "";
// 1. Captura o texto da IA (suporta diferentes formatos de saída do n8n)
if ($json.output && $json.output.length > 0 && $json.output[0].content && $json.output[0].content.length > 0) {
    iaText = $json.output[0].content[0].text;
} else if ($json.text) {
    iaText = $json.text;
} else if ($json.message && $json.message.content) {
    iaText = $json.message.content;
}

// 2. Transforma o Texto num Objeto JSON
let intentDecidida = "general";
try {
    iaText = iaText.replace(/```json/g, "").replace(/```/g, "").trim();
    const iaResponse = JSON.parse(iaText);
    intentDecidida = iaResponse.content || iaResponse.intent || "general";
} catch (error) {
    intentDecidida = "general"; 
}

// 3. Resgate da Mensagem Original
let parsedMessage = "";
try {
    if ($('Normaliza Campos Imagem').isExecuted) {
        parsedMessage = $('Normaliza Campos Imagem').first().json.message;
    } else if ($('Edit Fields').isExecuted) {
        parsedMessage = $('Edit Fields').first().json.message;
    } else {
        parsedMessage = "Mensagem não capturada.";
    }
} catch(e) {
    parsedMessage = "";
}

// 🔥 NOVO: REDE DE SEGURANÇA PARA SAUDAÇÕES (HARDCODED)
const GREETINGS_REGEX = /^(oi|ola|bom dia|boa tarde|boa noite|opa|hey|eae|ei|hello|hi|saudacoes|tudo bem)\b/i;
const normalizedMsg = parsedMessage.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^\w\s]/gi, "").trim();

if (parsedMessage.length <= 15 && GREETINGS_REGEX.test(normalizedMsg)) {
    intentDecidida = "saudacao"; // Força o roteamento correto para "olá"
}

return {
  json: {
    intent: intentDecidida, 
    message_original: parsedMessage,
    identity_gate_enabled: true
  }
};

