// 2. Prioridade de Negócio: Empresa/Agente Inativo
else if (!gov.empresa_ativa) {
    msg = "⚙️ *Manutenção de Sistema*\n\nO sistema da empresa está passando por uma atualização rápida. Por favor, tente novamente em alguns instantes.";
} 
else if (!gov.agente_ativo) {
    msg = "🤖 *Agente Indisponível*\n\nEste serviço de atendimento está pausado no momento. Em breve retornaremos!";
}

// 3. Prioridade Infra: Lotado
else if (gov.limite_atingido) {
    msg = "⏳ *Alta Demanda*\n\nUau! Temos muitas pessoas falando comigo agora. *Aguarde uns 2 minutinhos* e me mande um 'Oi' novamente para seguirmos?";
}

// 4. Caso o Agente não exista (Erro de Configuração)
else if (!gov.agente_encontrado) {
    msg = "🚫 *Falha de Configuração*\n\nNão foi possível localizar as instruções para este atendimento. (Ref: AgentNotFound)";
}

return {
    final_message: msg,
    blocking_reason: gov.user_banned ? 'BAN' : (gov.limite_atingido ? 'LIMIT' : 'MAINTENANCE')
};

/* 
  ⚙️ EXECUTOR DINÂMICO DE TOOLS (V20 - N8N NATIVE)
  - n8n Burro: Usando $http nativo do n8n (sem axios/fetch).
  - Suporta Múltiplas Ferramentas: Identifica qual tool a IA escolheu.
*/

// 1. Captura o que a IA enviou
const input = $json.parameters || $json;

// Se a IA não mandou tool_name, assumimos a financeira como padrão (migração híbrida)
const toolName = input.tool_name || 'Consultar_Vida_Financeira'; 

const agentData = $('Edit Fields').first().json;
const rpcData = $('Buscar Agente - RPC').first().json;

// 2. Busca a configuração da ferramenta no banco (Cockpit)
const toolDef = agentData.agent.tools.find(t => t.name === toolName);

if (!toolDef) {
  return JSON.stringify({ error: `Ferramenta '${toolName}' não encontrada no Cockpit deste agente.` });
}

// 3. Monta o pacote de dados para o banco/API
const params = {
  ...input,
  p_cpf: input.p_cpf || input.parameters0_Value || agentData.validated_doc,
  p_agent_id: agentData.agent_id,
  p_conversation_id: rpcData.conversation?.id
};

// 4. Faz a chamada usando o $http nativo do n8n
try {
  const response = await $http.request({
    method: 'POST',
    url: toolDef.url,
    headers: {
      'Content-Type': 'application/json',
      ...(toolDef.headers || {})
    },
    body: params,
  });

  // Retorna o resultado como STRING (exigência do n8n Custom Tool)
  return JSON.stringify(response);

} catch (error) {
  return JSON.stringify({ 
    error: `Erro na execução da ferramenta: ${toolName}`,
    message: error.message,
    detail: error.response?.body || 'Falha de conexão com a API'
  });
}

